<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$actor=(int)$_SESSION['user_id'];$role=$_SESSION['role'];$targetId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if(!$targetId){http_response_code(400);exit('Choose a valid team account.');}
$allowed=['system_admin'=>['sub_admin','admin','director'],'sub_admin'=>['admin','director'],'admin'=>['director'],'director'=>['sub_director','headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'],'sub_director'=>['headteacher','head_academic','department_head','assistant_academic','examination_officer','teacher','driver','hr','storekeeper','bursar'],'headteacher'=>['teacher','department_head']];
$db=db();$q=$db->prepare('SELECT id,name,email,username,role,status,created_at FROM users WHERE id=?');$q->execute([$targetId]);$target=$q->fetch();if(!$target){http_response_code(404);exit('Team account was not found.');}if($_SERVER['REQUEST_METHOD']==='GET'&&(!in_array($role,['system_admin','sub_admin'],true)||$targetId===$actor||$target['role']==='system_admin')){http_response_code(403);exit('You cannot analyze this account.');}
if(!in_array($role,['system_admin','sub_admin'],true)){$q=$db->prepare('SELECT 1 FROM school_memberships mine JOIN school_memberships theirs ON theirs.school_id=mine.school_id WHERE mine.user_id=? AND theirs.user_id=? LIMIT 1');$q->execute([$actor,$targetId]);if(!$q->fetchColumn()){http_response_code(403);exit('This account is outside your team access.');}}
$action=$_POST['action']??'';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($action==='reset'){if(!in_array($target['role'],$allowed[$role]??[],true)){http_response_code(403);exit('You cannot reset this role’s password.');}$password=rtrim(strtr(base64_encode(random_bytes(18)),'+/','-_'),'=');$db->beginTransaction();$q=$db->prepare('UPDATE users SET password_hash=?,must_change_password=TRUE WHERE id=?');$q->execute([password_hash($password,PASSWORD_DEFAULT),$targetId]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id) VALUES(?,?,?,?)');$q->execute([$actor,'reset_password','user',$targetId]);$db->commit();$_SESSION['created_account_credentials']=['name'=>$target['name'],'identifier'=>$target['email']?:$target['username'],'password'=>$password];header('Location: team.php');exit;}if($action==='suspend'){if(!in_array($role,['system_admin','sub_admin'],true)||$targetId===$actor||$target['role']==='system_admin'){http_response_code(403);exit('You cannot suspend this account.');}$newStatus=$target['status']==='active'?'disabled':'active';$q=$db->prepare('UPDATE users SET status=? WHERE id=?');$q->execute([$newStatus,$targetId]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$actor,$newStatus==='disabled'?'suspend':'reactivate','user',$targetId,json_encode(['status'=>$newStatus])]);header('Location: team.php');exit;}http_response_code(400);exit('Unknown team action.');}
$q=$db->prepare('SELECT s.name FROM school_memberships m JOIN schools s ON s.id=m.school_id WHERE m.user_id=? ORDER BY s.name');$q->execute([$targetId]);$schoolNames=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare('SELECT action,entity_type,created_at FROM audit_logs WHERE actor_id=? ORDER BY created_at DESC LIMIT 12');$q->execute([$targetId]);$activity=$q->fetchAll();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Analyze team member · ShuleLite</title><link rel="stylesheet" href="assets/app.css"></head><body><main class="auth-page"><section class="auth-shell"><a class="brand" href="team.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="auth-card"><div class="eyebrow">TEAM ACCOUNT</div><h1><?=e($target['name'])?></h1><p class="muted"><?=e($target['email'])?></p><p><strong>Role:</strong> <?=e(str_replace('_',' ',$target['role']))?><br><strong>Status:</strong> <?=e(ucfirst($target['status']))?><br><strong>Created:</strong> <?=e(date('j M Y',strtotime($target['created_at'])))?><br><strong>School access:</strong> <?=e($schoolNames?implode(', ',$schoolNames):'System wide')?></p><h2>Recent recorded activity</h2><?php if($activity):?><ul><?php foreach($activity as $event):?><li><?=e(str_replace('_',' ',$event['action']))?> · <?=e(str_replace('_',' ',$event['entity_type']))?> · <?=e(date('j M Y H:i',strtotime($event['created_at'])))?></li><?php endforeach;?></ul><?php else:?><p class="muted">No audited actions recorded for this account yet.</p><?php endif;?><a class="button primary full" href="team.php">Back to Team</a></div></section></main></body></html>
